		/** 
		 * Tests creating a new Operation.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Operation");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Operation" );

			try {            
				Operation entity = OperationService.getOperationInstance().createOperation( generateNewEntity() );
				thePrimaryKey = entity.getOperationId();
				LOGGER.info( "-- Successfully created a Operation with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Operation. 
		 */
		public Operation testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Operation" );

			Operation entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Operation with primary key" );
			msg.append( thePrimaryKey );
			
			OperationFetchOneSummary fetchOneSummary = new OperationFetchOneSummary( thePrimaryKey );

			try {
				entity = OperationService.getOperationInstance().getOperation( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Operation " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Operation.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Operation." );

			StringBuilder msg = new StringBuilder( "Failed to update a Operation : " );        
			Operation entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Operation." );

				// for use later on...
				thePrimaryKey = entity.getOperationId();

				OperationService proxy = OperationService.getOperationInstance();            
				proxy.updateOperation( entity );   

				LOGGER.info( "-- Successfully saved Operation - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Operation.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Operation." );

			try{
			    Operation entity = testRead(); 
				OperationService.getOperationInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Operation with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Operation with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Operations.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Operations:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Operation : " );        
			List<Operation> collection  = null;

			try {
				// call the static get method on the OperationService
				collection = OperationService.getOperationInstance().getAllOperation();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Operation entity = null;            
					Iterator<Operation> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getOperationId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

