		protected Operation generateNewEntity() {
			Operation entity = new Operation( null,  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  new TimeDuration(),  new TimeDuration(),  null,  null,  null,  OperationType.values()[0] );
			
			return( entity );
		}

